INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(163800, 0, 1638, 0, 0, 0, 'Thunder Bluff', 'Thunder Bluff is the capital of the tauren, raised by High Chieftain Cairne Bloodhoof on towering mesas at the northern end of Mulgore. For generations the tauren wandered as nomads, harried by the centaur, until Thrall and his orcs helped them win the plains, and Cairne built here a refuge where tauren of every tribe would be welcome. Great lifts, unique to the tauren, carry travelers up from the grass, while wind riders and a zeppelin from Orgrimmar come and go above. Long bridges of wood and rope join the central mesa, where Cairne keeps his tent among the traders and craftsmen, to three outer rises: Elder Rise of the druids and elders, Spirit Rise of the shamans, with the Forsaken quarter hidden beneath it in the Pools of Vision, and Hunter Rise of the hunters and warriors. The peace on the bluff is real, but not untroubled. The Elder Crone Magatha Grimtotem believes the tribes should be hers to lead, and some tauren wonder whether the pact with the Forsaken was made in haste.', 'warcraft.wiki.gg/wiki/Thunder_Bluff (founding by Cairne, refuge for every tribe, lifts unique to the tauren, rope bridges, layout of the rises, zeppelin added 3.2.0); warcraft.wiki.gg/wiki/Cairne_Bloodhoof (nomads, centaur, Thrall''s help, tribes united under him); DB: Mesa Elevator gameobjects 4170, 4171, 47296, 47297; Krendle Bigpockets 34766 Orgrimmar Zeppelin Master; Tal 2995 Wind Rider Master; warcraft.wiki.gg/wiki/Magatha_Grimtotem (believes she alone is fit to rule); quest 1049 description (too hasty was our pact)'),
(163801, 1, 1638, 1, 2, 0, 'The Central Mesa', 'The central mesa is the largest of Thunder Bluff''s heights, climbing in tiers known as the lower, middle and high rises. Its tents hold the city''s trade: the bank and the auction house, the inn where Innkeeper Pala greets every traveler like the wind on the plains, the forges of the Stonehoof smiths, the Winterhoof herbalists and alchemists, and the Mistrunner fishers and cooks. A great totem pole holds the wind rider roost, where Tal tends the beasts. Eyahn Eagletalon stitches a feathered headdress for a brother who will soon stand before the high chieftain. On the eastern heights rises the great tent of Cairne Bloodhoof, ringed by his Honor Guard.', 'warcraft.wiki.gg/wiki/Thunder_Bluff (central mesa divided into lower, middle and high rise; bank, inn and auction house on the lower rise; wind rider roost in the central totem pole; chieftain''s tent in the east); npc_text 822 (Innkeeper Pala gossip); quest 744 description (Eyahn''s brother before Chief Bloodhoof); DB spawns: Stonehoof, Winterhoof and Mistrunner vendors and trainers, Sage Truthseeker 3978, Honor Guard 3083 around Cairne 3057; posarea puts all in 1638'),
(163802, 1, 1638, 2, 0, 0, 'Elder Rise', 'Elder Rise, east of the central mesa, is the seat of the elders and the druids of Thunder Bluff. Arch Druid Hamuul Runetotem keeps his lodge here, and writings beside it set down the oldest legends of the Shu''halo: how the Earthmother breathed the plains into being, how in her grief she tore out her eyes to become An''she the sun and Mu''sha the moon, how Cenarius taught the first tauren to speak with the trees, and how the centaur fell upon the tribes once that teaching was forgotten. Piles of soil from Un''Goro rise beside the tents. Between the bridges stands the dwelling of Magatha Grimtotem, guarded by braves of her own tribe.', 'warcraft.wiki.gg/wiki/Elder_Rise (east of the central bluff, home of the Cenarion Circle and Council of Elders, Magatha''s hut between the two bridges, Hall of Elders); page_text 2295, 2298, 2305, 2308 (gameobjects 177207 Mists of Dawn, 177204 Sorrow of the Earthmother, 177205 Forestlord and the first Druids, 177209 Hatred of the Centaur, spawned beside Hamuul''s lodge); quest 3761 description (piles of dirt, Ghede); DB spawns: Hamuul 5769, Magatha 4046, Gorm 4309 and Cor 4310 Grimtotem on Elder Rise'),
(163803, 1, 1638, 3, 0, 0, 'Spirit Rise', 'Spirit Rise, northwest of the central mesa, is the heart of shamanic learning in Thunder Bluff, and the Skychaser tribe holds great sway here. Skychaser trainers teach young shamans to hear the spirits, sending them out to answer the call of fire, while Xanis Flameweaver guides those ready to seek the spirits of water and air. On the edge of the rise a zeppelin dock links the bluff with Orgrimmar across the Barrens. The rise hides more than it shows. Just below its cap, reached by a path that is easy to miss near the bridge, opens a warren of caves called the Pools of Vision, where the Forsaken keep their quarter.', 'warcraft.wiki.gg/wiki/Spirit_Rise (northwest of central bluff, center of shamanistic studies, Skychaser influence, zeppelin dock, Pools of Vision below); quests 1523 (Beram Skychaser), 1529 and 1532 (Xanis Flameweaver); quest 853 description (path well hidden on the Spirit Rise bluff); warcraft.wiki.gg/wiki/Pools_of_Vision (entrance beside the bridge to Spirit Rise); DB: Krendle Bigpockets 34766 on Spirit Rise'),
(163804, 1, 1638, 4, 0, 0, 'The Pools of Vision', 'Beneath Spirit Rise lie the Pools of Vision, a warren of caves that serves as the Forsaken quarter of Thunder Bluff. Mages and priests of the Undercity teach here, mages who return to the bluff by spell arrive among the pools, and a portal opens onto the Blasted Lands. Apothecary Zamah speaks for the Royal Apothecary Society, and the widow Clarice Foster nurses a grievance of her own. Not long ago a great earth elemental was loosed in the pools and drove the Forsaken out, until the gladiators Lo''Gosh and Broll Bearmantle, traveling with Rehgar Earthfury, brought the cavern roof down upon it. Some on Elder Rise suspected that Magatha Grimtotem had a hand in its coming.', 'warcraft.wiki.gg/wiki/Pools_of_Vision (Forsaken base, mages and priests, teleport arrival, the earth elemental, Lo''Gosh, Magatha publicizing the victory against Cairne); warcraft.wiki.gg/wiki/Magatha_Grimtotem (summoned the elemental to test Rehgar''s gladiators); DB: mage trainers 3047, 3048, 3049, priest trainers 3044, 3045, 3046, portal trainer 5957, Zamah 3419, Clarice Foster 5543 at z 97 to 112 under Spirit Rise; Portal to Blasted Lands gameobject 195142 at z 111.7; Poshken Hardbinder areaId 2197; quest 264 description; quest 1064 description (Zamah in the Pools of Vision below Spirit Rise); warcraft.wiki.gg/wiki/Destiny_Awaits! (World of Warcraft comic issue 3, January 2008: elemental drives out the Forsaken, Broll and Lo''Gosh bring down the cave, Hamuul suspects Magatha); WMOAreaTable.dbc: WMO 789 (Undeadcave) name set 1 groups 3052 to 3055 map to area 2197; vmap spawn in tile 001_31_33 uses name set 1'),
(163805, 1, 1638, 5, 0, 0, 'Hunter Rise', 'Hunter Rise, south of the central mesa, is the home of Thunder Bluff''s hunters and warriors. In Hunter''s Hall the Thunderhorns teach the bow and the bond between hunter and beast, Hesuwa Thunderhorn trains companions, and the Ragetotems drill young warriors. Melor Stonehoof sends seasoned hunters after quarry across the world. Mosarn''s forge outfits the braves who defend tauren lands, and he admits that the Grimtotem are among his best customers. Battlemasters call fighters to Warsong Gulch, Arathi Basin, Alterac Valley and the Eye of the Storm, and a battle mage sends volunteers to the struggle over Wintergrasp in Northrend, while training dummies stand ready for anyone eager to test an axe.', 'warcraft.wiki.gg/wiki/Hunter_Rise (south of the main bluff, hunters and warriors, Hunter''s Hall, battlemasters, training dummies); quest 11204 description (Mosarn outfits braves; Grimtotems fond of his work); DB spawns on 1641: Kary 3038, Holt 3039, Urek 3040 Thunderhorn; Torm 3041, Sark 3042, Ker 3043 Ragetotem; Hesuwa 10086; Melor 3441; Mosarn 4943; Kergul Bloodaxe 10360, Martin Lindsey 12198, Taim Ragetotem 7427, Althallen Brightblade 20388, Magister Dalhyr 35603 Wintergrasp Battle-Mage; training dummies'),
(163806, 2, 1638, 1, 2, 0, 'Cairne Bloodhoof', 'Cairne Bloodhoof, high chieftain of the tauren, was old when the Third War began, chief of the Bloodhoof tribe while the centaur hunted his people. He watched the young Warchief Thrall cut down centaur raiders and pledged the tauren to the Horde, and the orcs helped him win Mulgore in return. Here he raised Thunder Bluff, a refuge from the burdens of the world, and drew the scattered tribes together, and he stood behind the pact that brought the Forsaken into the Horde. He keeps his rival Magatha close, on Elder Rise, and still asks young tauren who reach his door to prove themselves in the hunt, beginning with the horn of the great kodo Arra''chea.', 'warcraft.wiki.gg/wiki/Cairne_Bloodhoof (Bloodhoof chieftain, centaur, meeting Thrall, Oracle, pledge to the Horde, Mulgore, Thunder Bluff, tribes united, invited Sylvanas, Magatha on Elder Rise: hold your enemies closer); npc_text 7013 (Cairne gossip: safe refuge from the burdens of the world); quests 775 reward text and 776 description; quest 1049 description (Cairne and the Forsaken pact)'),
(163807, 2, 1638, 2, 2, 0, 'Magatha Grimtotem', 'Magatha Grimtotem, the Elder Crone, is matriarch of the Grimtotem tribe and a powerful shaman. She became its matriarch through an arranged marriage and took the lead when her mate died in an unforeseen climbing accident, and she holds that she alone is fit to rule the tauren. Cairne lets her dwell on Elder Rise, keeping his rival close. She is the Forsaken''s warmest friend, hoping tauren ways can help them become human again, and she buys Highborne tablets from Azshara through the orc Jediga. She sends heroes to slay the serpent Arikara, claiming it stalks Cairne, though others cannot see why it would. Far from the bluff, in Stonetalon, Thousand Needles and Feralas, Grimtotem braves attack every outsider.', 'warcraft.wiki.gg/wiki/Magatha_Grimtotem (Elder Crone, arranged marriage, believes she alone should rule, supports the Forsaken); quest 3518 description and reward (proponent of the Forsaken alliance, Tablet of Beth''Amara, partnership with Jediga); quest 3562; quests 5088 description and reward (Arikara stalking Cairne; Motega cannot see why); npc_text 4473 (Rahauro handles most of her tasks); DB: Grimtotem creatures faction 16 (hostile to all) at Greatwood Vale (Stonetalon), Darkcloud Pinnacle (Thousand Needles), Feralas, Dustwallow; warcraft.wiki.gg/wiki/Magatha_Grimtotem, World of Warcraft section (arranged marriage, mate''s unforeseen climbing accident; game manual p.184: only she is fit to rule)'),
(163808, 2, 1638, 3, 2, 0, 'Arch Druid Hamuul Runetotem', 'Hamuul Runetotem, childhood friend of Cairne Bloodhoof, was moved by the druids who stood at Mount Hyjal, and afterward sought out Malfurion Stormrage to learn their ways. He became the first tauren druid in nearly twenty generations and now leads the druids of the Cenarion Circle on Elder Rise. He helped persuade Thrall to accept the Forsaken into the Horde. The earth keeps many secrets, he teaches, and some must stay secret for the good of all. He has walked the Emerald Dream seeking the taint in the Barrens, warns that things in the Dream are not what the druids believed, and urges those he sends to Moonglade to look past the growing tension between Darnassus and the Circle.', 'warcraft.wiki.gg/wiki/Hamuul_Runetotem (friend of Cairne, Hyjal, Malfurion, Fandral''s objection, first tauren druid in nearly twenty generations, archdruid, Forsaken alliance); npc_text 2284 (Hamuul gossip); quest 1490 description (entered the land of dreams); quest 3369 reward text (Emerald Dream not as we thought); quest 1123 description (tensions between Darnassus and the Cenarion Circle)'),
(163809, 2, 1638, 4, 2, 0, 'Nara Wildmane', 'Nara Wildmane is a young druid of Elder Rise with a fierce spirit. When Hamuul Runetotem entered the land of dreams in search of the taint creeping through the Barrens, the old druid could not stay long, but Nara remained, and saw the twisted, scaled faces of the Druids of the Fang who lair in the Wailing Caverns. She has traveled as far as the Valley of the Watchers in Tanaris and stood outside the sealed gates of Uldum, a place most think a myth. She knows the wildkin as guardians made by the night elf goddess Elune, and she grieved for her friend Mulgris Deepriver when his glyphed branch was carried home from his body in the Plaguelands.', 'quest 1490 description and reward; quest 914 description and reward; quest 2965 reward text (has been outside Uldum); quest 4883 reward text (wildkin created by Elune); quest 4987 reward text (Mulgris was a good friend); warcraft.wiki.gg/wiki/Nara_Wildmane'),
(163810, 2, 1638, 5, 2, 0, 'Apothecary Zamah', 'Apothecary Zamah is a scholar of the Royal Apothecary Society and the Forsaken''s emissary to the tauren, working from the Pools of Vision. Her heart no longer beats, she says, yet she still grieves for the wounded spirits of Stonetalon. She serves the Dark Lady openly. She studies serpentbloom, a rare herb from the darkest depths of the Wailing Caverns that she believes holds great potential, though many she sent for it never came back, and she takes in the rendered spores her colleague Helbrim gathers in the Barrens. When the tauren ask the Forsaken for help, Zamah gives it gladly, and if the methods are cruel, she sees no reason for guilt.', 'quest 1064 description and reward (scholar and emissary of the Forsaken; heart beats no longer); quest 962 description and request text; quest 853 reward text; quest 1086 reward text (ignore any guilt)'),
(163811, 2, 1638, 6, 2, 0, 'Sage Truthseeker', 'Sage Truthseeker is one of the sages of Thunder Bluff, historians whose learning is known throughout the Horde, and he keeps his tent on the central mesa. Visitors who march into his tent with purpose in their stride are asked whether they seek his counsel, or a mystery of the universe revealed. His true study is the secrets the earth holds tightly, and when a small copy of the platinum discs of Uldaman came into his hands, he set his other studies aside to learn their workings. He is loyal to Cairne and would trust the chieftain with his life. It is the others around him that he does not trust, least of all the Forsaken.', 'quest 2280 description, request and reward (sages of Thunder Bluff, historians known throughout the Horde; secrets the earth has held); quest 2440 description; quest 1049 description and request text (trusts Cairne with his life, not others; Forsaken deceit); DB: spawn at -1176,157, posarea 1638; quest 2440 description (I shall focus my energies on these discs)'),
(163812, 2, 1638, 7, 2, 0, 'Melor Stonehoof', 'Melor Stonehoof is a master hunter of Hunter Rise, and older hunters send him the most promising of the young. Old Skorn Whitecloud of Bloodhoof Village tests them first with the claws of Mulgore''s flatland prowlers; Melor then sends them on to the Barrens, whose strong-willed beasts teach a young hunter''s spirit to grow. Tauren hunt, he teaches, at times for food, at times for honor and at times to earn the Earthmother''s teachings, and every hunt carries its own lesson. When his students have grown, he sends word for them to return, for there are harder hunts still.', 'quest 861 description and reward (Skorn''s test, Melor on Hunter''s Rise); quest 860 description (Barrens beasts strong-willed, spirit will grow); quest 1131 description (hunt for food, honor, the Earthmother''s teachings); quest 1130 description (Melor sends word); quest 1131 reward (lesson this day)'),
(163813, 2, 1638, 8, 2, 0, 'Tahu Sagewind and Aponi Brightmane', 'Near the druids'' lodge on Elder Rise, two young tauren pass the days in talk. Aponi Brightmane, a warrior, was sent home from the war in Northrend with an infected wound in her arm, and she chafes at sitting idle while her band fights on. Tahu Sagewind, a student of Hamuul Runetotem, tends her. He has heard the elves of Moonglade speak of their moon goddess, and he muses that what Hamuul teaches is the lore of the night elves. The Shu''halo strive for balance in all things, and he wonders whether the druids have overlooked some part of it. Aponi answers with hope: the dawn will come, and even on the glacier the sun breaks through the gloom.', 'creature_text 34528 and 34526 (their conversation); npc_text 14560 and 14561 (gossip); quest 13986 description and reward; warcraft.wiki.gg/wiki/Tahu_Sagewind (3.2/3.3 dialogue on Elder Rise); quest 13986 ender Aponi 34526; starter Sorn Proudmane 35471 in Dalaran (map 571); both Elder Rise spawns permanent, phaseMask 1, no game_event'),
(163814, 2, 1638, 9, 2, 0, 'Auld Stonespire', 'Auld Stonespire honors Cairne Bloodhoof for uniting the tauren on the bluff, but he cannot forgive the past as easily as some. For decades his people lived in the southern Barrens, on land they held holy, until enemy after enemy drove them out. Chief among them, in his eyes, are the quilboar of Razorfen Kraul, where the crone Charlga Razorflank now musters a foul army. To drive a people from holy land, he says, is a sin that earns the most severe revenge, and only when Razorflank''s heart is brought to him will he be able to die in peace.', 'quest 1102 description, request and reward'),
(163815, 3, 1638, 1, 2, 0, 'Forsaken Aid', 'The spirits of Stonetalon cry out as the Venture Company strips the mountains of their forests, and the Horde shaman Seereth Stonebreak, unable to calm them alone, sends for help to the one tauren elder she knows by name: Magatha Grimtotem. The Elder Crone''s answer is unexpected. To heal the land, she says, its disease must first be removed, and the Forsaken know disease better than anyone; asking their help will also deepen the trust between the two peoples. Her messenger goes to Apothecary Zamah in the Pools of Vision, who wants extreme measures, but no bloodshed. Her colleague Lydon in Tarren Mill brews a toxin to bleed the violence from the goblins and leave them docile, made with the blood of innocents taken from Syndicate shadow mages at Durnholde Keep. Zamah fits it into a fogger, and it is planted at the Venture Company''s small sky port in Stonetalon, in the hope that it spreads to their headquarters. Feel no guilt, Zamah says afterward. Never shy from dark paths, if they lead to victory.', 'quests 1061 to 1063 (Stonetalon start, Seereth, The Elder Crone); quest 1064 description; creature_text 4046 (Magatha sends a messenger to Zamah); quests 1065, 1066, 1067, 1086 descriptions and reward texts'),
(163816, 3, 1638, 2, 2, 0, 'Magatha''s Lost Clansman', 'Troggs have begun to climb out of the lava filled depths beneath Orgrimmar into Ragefire Chasm. Magatha Grimtotem, it is said, sought to make peace with them, but they turned on her diplomats and killed them, and now she names them a threat to the whole Horde. Her servant Rahauro sends heroes into the Chasm to thin the troggs before they can overwhelm the orcs from below. The troggs were not all that drew the Elder Crone''s eye. One of her clansmen, Maur Grimtotem, found something peculiar in the Chasm and never came out to show her. His body lies in the dark, battered by clubs and fists, still clutching a satchel to his chest as though he died protecting it. The troggs cared nothing for it. Rahauro accepts the satchel for his mistress without a word of what it holds, and muses that one day someone should learn where such creatures come from, and what they truly want.', 'quest 5723 description and reward; quest 5722 description and reward; quest 5724 description, request and reward; npc_text 4473 (Rahauro gossip)'),
(163817, 3, 1638, 3, 2, 0, 'Portents of Uldum', 'When the miniature discs carried out of Uldaman reached Thunder Bluff, Sage Truthseeker sensed in them secrets the earth had held for ages, and talking them over with the druid Nara Wildmane, he found an unexpected thread. The translated glyphs name Uldum, a place most think a myth. Nara knows better. In her travels she reached the Valley of the Watchers in the Tanaris desert and stood outside its sealed gates. Together the sage and the druid sent the discs south, unsure whether anything at all would happen. Something did: a guardian woke before the gates, but the discs alone could not open them, and the missing Plates of Uldum are needed first. Nara does not know whether to be excited or terrified, and she fears that secrets of the earth which could destroy everyone may lie within. For now the sages wait, sifting their lore for where the plates might lie, and promise that Uldum will call their helper back.', 'quest 2278 and 2280 descriptions (miniature discs, sages of Thunder Bluff); quest 2440 description; quest 2965 description and reward; quests 2966, 2954, 2967 descriptions and rewards; quest 2968 description and reward'),
(163818, 3, 1638, 4, 2, 0, 'Morrowgrain Research', 'Innkeepers across the Horde pass on a request: Arch Druid Hamuul Runetotem needs seasoned helpers for a dangerous research project of the Cenarion Circle. The soil of Un''Goro Crater is said to be rich with potent magic, and the Circle wants it in great quantity. It is unloaded onto piles on Elder Rise under the eye of Ghede, a druid who barks at every helper like a drill sergeant at a raw recruit and has no patience for anything cute or funny. In a pouch of evergreen the soil nourishes Tharlendris seeds, which blossom into an array of potent herbs. One of them, morrowgrain, is a mystery the Arch Druid hopes to unravel. His daughter Bashana hands out the costly seeds, asks helpers to share their price, and gathers the morrowgrain ten at a time. The night elves are studying the same herbs, to what end no one knows, and Hamuul means to keep collecting until the secret of the herb is found.', 'quests 3762, 936, 3784 descriptions (Pala, Gryshka, Norman); quest 3761 description, request and reward; npc_text 2333 (Ghede gossip); quest 3782 description and reward (Evergreen Pouch, Tharlendris seeds, my daughter Bashana, cost); quests 3786 and 3804 texts (night elves conducting similar research)'),
(163819, 3, 1638, 5, 2, 0, 'The Hunter''s Path', 'Once tales of a young champion''s deeds reach him, Melor Stonehoof sends word, and the hunts he sets after that are of another kind. The first is not for food, honor or wisdom. The hyena Steelsnap is a tyrant of the Thousand Needles, living outside the Earthmother''s blessing, drawing other hyenas to him and spreading fear and bloodshed among gentler beasts, and his death cleanses the canyons of a terrible taint. The second hunt leads far from Kalimdor, to the Alterac Mountains and the white yeti Frostmaw, so elusive that Melor writes out on a scroll how he may be lured. Both strength and cunning are needed, and both are proven. Another hunt is a mercy. Deadmire, an ancient crocolisk of Dustwallow Marsh, still moves with the speed of youth, but his aging body tortures the great spirit within it, and the hunter''s task is to lead him to peace. Such is the way of the hunter, Melor teaches, and in time it leads through all the Earthmother''s lands.', 'quest 1130 description; quest 1131 description and reward; quest 1136 description and reward; quest 1205 description and reward'),
(163820, 3, 1638, 6, 2, 0, 'Too Hasty a Pact', 'The tauren helped open the way for the Forsaken into the Horde, and not every voice on the bluff believes it was wise. Some are moved by pity: the alchemist Bena Winterhoof wept when she first saw the undead, and then the Earthmother sang in her blood and told her to save them. Magatha Grimtotem is among the elders who champion them. Sage Truthseeker is not persuaded. The Earthen Ring, he grants, meant only good toward the plagued, but who can say what voices whisper in the ears of the Elder Council? The Forsaken have a history thick with deceit, the pact was made too quickly, and Cairne might have done better to heed the warnings from Orgrimmar. Before he advises his chieftain he wants every scrap of knowledge he can find, and so he sends trusted helpers to the Scarlet Monastery in Tirisfal Glades, where crazed human zealots guard the Compendium of the Fallen. Their methods are born of madness, but their research may yet serve.', 'quest 1049 description, request and reward; npc_text 5079 (Bena Winterhoof gossip); quest 3518 description (Magatha proponent of the alliance); warcraft.wiki.gg/wiki/Hamuul_Runetotem and Cairne_Bloodhoof (tauren role in bringing the Forsaken into the Horde)');
